{"teaching_intent":"让学生通过操控初始高度、初速度、抛射角、质量与重力加速度，观察并验证：水平/斜抛运动可分解为匀速水平运动与匀变速竖直运动；速度方向随时间持续向下偏转；加速度与合力始终竖直向下且大小不变；动能、势能在转化中机械能守恒；落地时间与竖直方向条件相关，射程由水平速度与飞行时间共同决定；最高点、落地时刻等临界状态随参数同步变化。","html":"<!DOCTYPE html>
<html lang='zh-CN'>
<head>
<meta charset='UTF-8'>
<meta name='viewport' content='width=device-width, initial-scale=1.0'>
<title>平抛/斜抛运动通用物理模型</title>
<style>
:root{--bg:#f1f5f9;--panel:#fff;--text:#0f172a;--accent:#0ea5e9;--accent2:#f59e0b;--accent3:#ef4444;--line:#64748b;}
*{box-sizing:border-box;}
body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;background:var(--bg);color:var(--text);line-height:1.5;}
.app{max-width:980px;margin:0 auto;padding:12px;}
header{margin-bottom:10px;}
h1{font-size:1.35rem;margin:0;}
.hl{color:var(--accent);font-weight:700;}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:10px;margin-bottom:10px;}
.card{background:var(--panel);border-radius:10px;padding:10px;box-shadow:0 1px 3px rgba(0,0,0,.08);}
.card.wide{grid-column:1/-1;}
.card small{display:block;color:var(--line);font-size:.75rem;margin-bottom:4px;}
.card .unit{font-size:.8rem;color:var(--line);margin-left:2px;}
.stage{height:clamp(240px,42vh,420px);background:var(--panel);border-radius:12px;overflow:hidden;box-shadow:0 1px 3px rgba(0,0,0,.08);margin-bottom:10px;}
svg{width:100%;height:100%;}
.energy{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:10px;background:var(--panel);padding:12px;border-radius:12px;box-shadow:0 1px 3px rgba(0,0,0,.08);}
.bar{display:flex;flex-direction:column;align-items:center;}
.bar .label{font-size:.8rem;margin-bottom:6px;}
.track{width:34px;height:120px;background:#e2e8f0;border-radius:6px;overflow:hidden;position:relative;}
.fill{position:absolute;bottom:0;width:100%;transition:height .05s linear;}
.fill.ek{background:var(--accent);}
.fill.ep{background:#22c55e;}
.fill.me{background:var(--line);}
.controls{display:grid;grid-template-columns:1fr 1fr;gap:12px;}
.group{background:var(--panel);border-radius:12px;padding:12px;box-shadow:0 1px 3px rgba(0,0,0,.08);}
.group h3{font-size:.95rem;margin:0 0 10px;}
label{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-bottom:10px;font-size:.85rem;min-height:44px;}
label input[type=range]{flex:1;min-width:80px;height:44px;}
label span{width:54px;text-align:right;font-variant-numeric:tabular-nums;}
button{background:var(--text);color:#fff;border:none;border-radius:8px;min-height:44px;min-width:64px;padding:0 14px;font-size:.9rem;touch-action:manipulation;}
button:active{opacity:.85;}
#playBtn{background:var(--accent);}
#rateVal{color:var(--text);font-weight:700;}
.summary{font-size:.8rem;color:var(--line);margin-top:6px;}
@media(max-width:720px){
.controls{grid-template-columns:1fr;}
.stage{height:clamp(220px,38vh,360px);}
.energy{grid-template-columns:repeat(3,1fr);}
}
@media(max-width:375px){
h1{font-size:1.1rem;}
.card{padding:8px;}
}
</style>
</head>
<body>
<!--HARNESS_PRIMITIVES-->
<!--HARNESS_MODEL-->
<!--HARNESS_INPUT-->

<div class='app'>
<header>
<h1>平抛/斜抛运动通用物理模型</h1>
<p>拖动滑块改变条件，观察<span class='hl'>速度方向</span>、<span class='hl'>落地时间</span>与<span class='hl'>射程</span>如何变化</p>
</header>

<section class='stats'>
<div class='card'><small>物理时间</small><div><span data-physical-time>0.00</span><span class='unit'>s</span></div></div>
<div class='card'><small>演示倍率</small><div><span data-demo-time>×1.00</span></div></div>
<div class='card wide'><small>状态 / 结果</small><div data-readout>准备就绪</div><div class='summary' id='summary'></div></div>
</section>

<div class='stage'>
<svg id='traj' viewBox='0 0 100 50' preserveAspectRatio='xMidYMid meet'>
<defs>
<marker id='vA' markerWidth='8' markerHeight='8' refX='7' refY='4' orient='auto'><path d='M0,0 L8,4 L0,8 z' fill='#0ea5e9'/></marker>
<marker id='aA' markerWidth='8' markerHeight='8' refX='7' refY='4' orient='auto'><path d='M0,0 L8,4 L0,8 z' fill='#f59e0b'/></marker>
<marker id='fA' markerWidth='8' markerHeight='8' refX='7' refY='4' orient='auto'><path d='M0,0 L8,4 L0,8 z' fill='#ef4444'/></marker>
</defs>
<line id='ground' x1='0' y1='50' x2='100' y2='50' stroke='#94a3b8' stroke-width='0.4'/>
<path id='orbit' fill='none' stroke='#64748b' stroke-width='0.25' stroke-dasharray='1,0.5'/>
<g id='vec'>
<line id='vvec' stroke='#0ea5e9' stroke-width='0.18' marker-end='url(#vA)' vector-effect='non-scaling-stroke'/>
<line id='avec' stroke='#f59e0b' stroke-width='0.18' marker-end='url(#aA)' vector-effect='non-scaling-stroke'/>
<line id='fvec' stroke='#ef4444' stroke-width='0.18' marker-end='url(#fA)' vector-effect='non-scaling-stroke'/>
</g>
<circle id='ball' r='0.5' fill='#0f172a' stroke='#fff' stroke-width='0.15'/>
<circle id='apex' r='0.25' fill='none' stroke='#22c55e' stroke-width='0.2' opacity='0'/>
</svg>
</div>

<div class='energy'>
<div class='bar'><span class='label'>动能 Ek</span><div class='track'><div id='ekBar' class='fill ek'></div></div></div>
<div class='bar'><span class='label'>势能 Ep</span><div class='track'><div id='epBar' class='fill ep'></div></div></div>
<div class='bar'><span class='label'>机械能 E</span><div class='track'><div id='meBar' class='fill me'></div></div></div>
</div>

<section class='controls'>
<div class='group params'>
<h3>场景参数</h3>
<label>高度 h<input type='range' data-control='height' min='0' max='50' step='1' value='20'><span data-v='height'>20 m</span></label>
<label>初速 v<input type='range' data-control='speed' min='0' max='30' step='1' value='10'><span data-v='speed'>10 m/s</span></label>
<label>角度 θ<input type='range' data-control='angle' min='0' max='90' step='1' value='0'><span data-v='angle'>0°</span></label>
<label>质量 m<input type='range' data-control='mass' min='0.1' max='5' step='0.1' value='1'><span data-v='mass'>1.0 kg</span></label>
<label>重力 g<input type='range' data-control='gravity' min='1' max='20' step='0.5' value='10'><span data-v='gravity'>10 m/s²</span></label>
</div>
<div class='group playback'>
<h3>播放控制</h3>
<button id='playBtn' data-play>播放</button>
<button data-replay>重放</button>
<label>倍率<input type='range' id='rate' min='0.25' max='2' step='0.25' value='1'><span id='rateVal'>×1.00</span></label>
<label>时间轴<input type='range' id='scrub' min='0' max='1' step='0.001' value='0'><span id='scrubVal'>0%</span></label>
</div>
</section>
</div>

<script>
(function(){
const model=globalThis.coursewareModel;
const primitives=globalThis.CoursewarePrimitives;
const harnessInput=globalThis.__HARNESS_INPUT__||{};
const defaults={mode:'horizontal',angle_deg:0,g_m_s2:10,mass_kg:1,speed_m_s:10,x0_m:0,y0_m:20};
let scenario=Object.assign({},defaults,harnessInput.scenario||{});
let flightTime=0,range=0,maxHeight=0,optimalAngle=0;
let pathStates=[],maxE=1,vbH=50,vbW=100,xMin=0;
let physicalTime=0,rate=1,isPlaying=false,rafId=null,lastTs=null,timeline=null;

const els={
svg:document.getElementById('traj'),ground:document.getElementById('ground'),orbit:document.getElementById('orbit'),
ball:document.getElementById('ball'),vvec:document.getElementById('vvec'),avec:document.getElementById('avec'),fvec:document.getElementById('fvec'),apex:document.getElementById('apex'),
ekBar:document.getElementById('ekBar'),epBar:document.getElementById('epBar'),meBar:document.getElementById('meBar'),
phys:document.querySelector('[data-physical-time]'),demo:document.querySelector('[data-demo-time]'),readout:document.querySelector('[data-readout]'),summary:document.getElementById('summary'),
playBtn:document.getElementById('playBtn'),scrub:document.getElementById('scrub'),scrubVal:document.getElementById('scrubVal'),rateVal:document.getElementById('rateVal')
};

function fmt(n){return Number(n).toFixed(2);}
function sample(times){return model.sample({scenario:scenario,times_s:times});}

function applyScenarioToControls(){
document.querySelector('[data-control=height]').value=scenario.y0_m;
document.querySelector('[data-control=speed]').value=scenario.speed_m_s;
document.querySelector('[data-control=angle]').value=scenario.angle_deg;
document.querySelector('[data-control=mass]').value=scenario.mass_kg;
document.querySelector('[data-control=gravity]').value=scenario.g_m_s2;
}
function readScenario(){
scenario.angle_deg=+document.querySelector('[data-control=angle]').value;
scenario.speed_m_s=+document.querySelector('[data-control=speed]').value;
scenario.y0_m=+document.querySelector('[data-control=height]').value;
scenario.mass_kg=+document.querySelector('[data-control=mass]').value;
scenario.g_m_s2=+document.querySelector('[data-control=gravity]').value;
scenario.mode=(scenario.angle_deg===0)?'horizontal':'oblique';
}
function setControlLabels(){
document.querySelector('[data-v=height]').textContent=fmt(scenario.y0_m)+' m';
document.querySelector('[data-v=speed]').textContent=fmt(scenario.speed_m_s)+' m/s';
document.querySelector('[data-v=angle]').textContent=fmt(scenario.angle_deg)+'°';
document.querySelector('[data-v=mass]').textContent=fmt(scenario.mass_kg)+' kg';
document.querySelector('[data-v=gravity]').textContent=fmt(scenario.g_m_s2)+' m/s²';
}
function updateSummary(){
els.summary.textContent='飞行时间 T='+fmt(flightTime)+' s · 射程 R='+fmt(range)+' m · 最大高度 H='+fmt(maxHeight)+' m · 等高点最佳角='+fmt(optimalAngle)+'°';
}
function computePath(){
const n=Math.min(400,Math.max(100,Math.ceil(flightTime*60)));
const times=[];
for(let i=0;i<=n;i++) times.push(i/n*flightTime);
const res=sample(times);
pathStates=res.states||[];
let d='';
pathStates.forEach((s,i)=>{d+=(i?' L':' M')+(s.x_m)+','+(vbH-s.y_m);});
els.orbit.setAttribute('d',d);
maxE=Math.max(1,Math.max(...pathStates.map(s=>s.mechanical_j||0)));
}
function updateViewBox(){
const padX=Math.max(2,range*0.12),padY=Math.max(2,maxHeight*0.12);
xMin=scenario.x0_m-1;
vbW=Math.max(10,range+padX-xMin);
vbH=Math.max(6,scenario.y0_m,maxHeight+padY);
els.svg.setAttribute('viewBox',xMin+' 0 '+vbW+' '+vbH);
els.ground.setAttribute('x1',xMin);
els.ground.setAttribute('x2',xMin+vbW);
els.ground.setAttribute('y1',vbH);
els.ground.setAttribute('y2',vbH);
const r=Math.max(0.25,Math.min(vbW,vbH)/70);
els.ball.setAttribute('r',r);
els.apex.setAttribute('r',r*0.5);
}
function setArrow(el,x,y,vx,vy,scale){
const len=Math.hypot(vx,vy);
if(len<0.001){el.setAttribute('x1',x);el.setAttribute('y1',y);el.setAttribute('x2',x);el.setAttribute('y2',y);return;}
el.setAttribute('x1',x);el.setAttribute('y1',y);
el.setAttribute('x2',x+vx*scale);el.setAttribute('y2',y-vy*scale);
}
function render(){
if(flightTime<=0){return;}
const res=sample([physicalTime]);
const s=res.states[0];
const bx=s.x_m,by=vbH-s.y_m;
els.ball.setAttribute('cx',bx);els.ball.setAttribute('cy',by);
setArrow(els.vvec,bx,by,s.vx_m_s,s.vy_m_s,0.15);
setArrow(els.avec,bx,by,s.ax_m_s2,s.ay_m_s2,0.05);
setArrow(els.fvec,bx,by,s.ax_m_s2*scenario.mass_kg,s.ay_m_s2*scenario.mass_kg,0.05);
els.ekBar.style.height=(s.kinetic_j/maxE*100)+'%';
els.epBar.style.height=(s.potential_j/maxE*100)+'%';
els.meBar.style.height=(s.mechanical_j/maxE*100)+'%';
els.phys.textContent=fmt(physicalTime);
const v=Math.hypot(s.vx_m_s,s.vy_m_s);
els.readout.textContent='x='+fmt(s.x_m)+' m, y='+fmt(s.y_m)+' m, v='+fmt(v)+' m/s, vx='+fmt(s.vx_m_s)+' m/s, vy='+fmt(s.vy_m_s)+' m/s, Ek='+fmt(s.kinetic_j)+' J, Ep='+fmt(s.potential_j)+' J';
els.scrub.value=physicalTime/flightTime;
els.scrubVal.textContent=Math.round(physicalTime/flightTime*100)+'%';
if(physicalTime>=flightTime){isPlaying=false;updatePlayBtn();}
}
function updateApex(){
if(maxHeight>scenario.y0_m+0.01){
const apexS=pathStates.reduce((a,b)=>b.y_m>a.y_m?b:a,pathStates[0]);
els.apex.setAttribute('cx',apexS.x_m);
els.apex.setAttribute('cy',vbH-apexS.y_m);
els.apex.setAttribute('opacity','1');
}else{els.apex.setAttribute('opacity','0');}
}
function updateAll(){
readScenario();setControlLabels();
const ev=sample([0]).events||{};
flightTime=ev.flight_time_s||0;range=ev.range_m||0;maxHeight=ev.max_height_m||0;optimalAngle=ev.optimal_equal_height_angle_deg||0;
updateSummary();
updateViewBox();
computePath();
updateApex();
physicalTime=0;isPlaying=false;updatePlayBtn();
makeTimeline();render();
}
function makeTimeline(){
if(timeline&&typeof timeline.pause==='function') timeline.pause();
timeline=primitives.createTimeline({duration:flightTime,rate:rate,autoplay:false,onUpdate:(arg)=>{
let t=arg;if(typeof arg==='object'&&arg!==null)t=(arg.time!=null?arg.time:arg.progress*flightTime);
physicalTime=Math.max(0,Math.min(flightTime,t));render();
},onComplete:()=>{isPlaying=false;updatePlayBtn();}});
}
function updatePlayBtn(){els.playBtn.textContent=isPlaying?'暂停':'播放';}
function updateRate(){els.rateVal.textContent='×'+rate.toFixed(2);els.demo.textContent='×'+rate.toFixed(2);}
function play(){isPlaying=true;updatePlayBtn();if(timeline&&typeof timeline.play==='function'){timeline.play();}else{lastTs=null;loop();}}
function pause(){isPlaying=false;updatePlayBtn();if(timeline&&typeof timeline.pause==='function'){timeline.pause();}else{cancelAnimationFrame(rafId);}}
function loop(ts){if(!isPlaying)return;if(!lastTs)lastTs=ts;const dt=(ts-lastTs)/1000;lastTs=ts;physicalTime+=dt*rate;if(physicalTime>=flightTime){physicalTime=flightTime;isPlaying=false;updatePlayBtn();}render();if(isPlaying)rafId=requestAnimationFrame(loop);}

els.playBtn.addEventListener('click',()=>{if(isPlaying)pause();else play();});
document.querySelector('[data-replay]').addEventListener('click',()=>{physicalTime=0;if(timeline&&typeof timeline.seek==='function')timeline.seek(0);play();});
els.scrub.addEventListener('input',()=>{pause();physicalTime=+els.scrub.value*flightTime;if(timeline&&typeof timeline.seek==='function')timeline.seek(physicalTime);render();});
document.getElementById('rate').addEventListener('input',(e)=>{rate=+e.target.value;updateRate();if(timeline&&typeof timeline.setRate==='function')timeline.setRate(rate);});
document.querySelectorAll('[data-control]').forEach(el=>el.addEventListener('input',()=>{pause();updateAll();}));
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});

applyScenarioToControls();
updateAll();
})();
<\/script>
<\/body>
<\/html>"}
